mapper.select:
SELECT DATE(create_time) as date, COUNT(1) as count FROM favorite_categories WHERE user_id = #{userId}
AND create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
GROUP BY DATE(create_time) ORDER BY date DESC
